/**
 * The README's eval summary (#102): each recording set's latest gated metrics,
 * from `evals/history.jsonl`, between two markers. Generated like the report,
 * so the numbers a visitor reads first can't drift from the measured ones:
 * `pnpm eval:replay` rewrites the block and `--check` fails when it differs.
 */
import { seriesOf } from "./charts.js";
import { type HistoryEntry, sameSet, setName } from "./history.js";
import { percent, withRange } from "./report.js";

export const SUMMARY_START =
  "<!-- eval-summary:start · generated by `pnpm eval:replay` from evals/history.jsonl: don't edit -->";
export const SUMMARY_END = "<!-- eval-summary:end -->";

/** The block between the markers, markers included. */
export function renderSummary(history: readonly HistoryEntry[]): string {
  const rows = seriesOf(history).flatMap((set) => {
    const entry = history.findLast((e) => sameSet(e, set));
    if (entry === undefined) return [];
    const rate = (
      key: "accuracy" | "approvedFraudRate" | "autoApprovedFraudRate",
    ) =>
      entry.spread === undefined
        ? percent(entry.gated[key])
        : withRange(entry.gated[key], entry.spread.gated[key]);
    return [
      `| \`${setName(set)}\` | ${entry.id} · ${entry.date} | ${String(entry.runs ?? 1)} | ${String(entry.gated.cases)} | ${rate("accuracy")} | ${rate("approvedFraudRate")} | ${rate("autoApprovedFraudRate")} | ${percent(entry.gated.escalationRate)} |`,
    ];
  });
  return [
    SUMMARY_START,
    // Prettier would realign the table and break the byte-for-byte check.
    "<!-- prettier-ignore-start -->",
    "| Model | Latest entry | Runs per case | Gated cases | Accuracy | Approved fraud | Auto-approved fraud | Escalated |",
    "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ...(rows.length === 0
      ? ["| — | no entries yet | — | — | — | — | — | — |"]
      : rows),
    "<!-- prettier-ignore-end -->",
    SUMMARY_END,
  ].join("\n");
}

/**
 * The README with its summary block replaced, or null when it has no markers
 * to replace between.
 */
export function withSummary(readme: string, summary: string): string | null {
  const start = readme.indexOf(SUMMARY_START);
  const end = readme.indexOf(SUMMARY_END);
  if (start === -1 || end === -1 || end < start) return null;
  return (
    readme.slice(0, start) + summary + readme.slice(end + SUMMARY_END.length)
  );
}
